import{_ as e}from"./chunks/100.I7A0VXqr.js";import{_ as o,o as a,c as n,ak as r}from"./chunks/framework.DC-k2h36.js";const i="/projects/esp32Sensor/en/latest/assets/1.CQPJMu_9.webp",s="/projects/esp32Sensor/en/latest/assets/2._h14dSZ5.webp",l="/projects/esp32Sensor/en/latest/assets/3.CRN76f1y.webp",c="/projects/esp32Sensor/en/latest/assets/4.BUZt4JfD.webp",d="/projects/esp32Sensor/en/latest/assets/5.Ce-tdVrD.webp",y=JSON.parse('{"title":"3. Knob Module","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Knob Module.md","filePath":"docs/3. Knob Module.md"}'),h={name:"docs/3. Knob Module.md"};function p(g,t,m,u,_,b){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="_3-knob-module" tabindex="-1">3. Knob Module <a class="header-anchor" href="#_3-knob-module" aria-label="Permalink to &quot;3. Knob Module&quot;">​</a></h1><h2 id="_3-1-introduction" tabindex="-1">3.1 Introduction <a class="header-anchor" href="#_3-1-introduction" aria-label="Permalink to &quot;3.1 Introduction&quot;">​</a></h2><p>The knob module consists of a potentiometer that varies its resistance within a defined range when rotated, thereby adjusting the output voltage. It pairs with various modules to implement diverse functions, such as regulating fan speed or controlling light brightness.</p><img loading="lazy" height="1156" width="1156" src="'+i+'" class="common_img" style="width:300px;"><h2 id="_3-2-technical-specifications" tabindex="-1">3.2 Technical Specifications <a class="header-anchor" href="#_3-2-technical-specifications" aria-label="Permalink to &quot;3.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Adjustment method</td><td style="text-align:center;">Rotary adjustment</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 35.8 mm</td></tr></tbody></table><h2 id="_3-3-operating-principle" tabindex="-1">3.3 Operating Principle <a class="header-anchor" href="#_3-3-operating-principle" aria-label="Permalink to &quot;3.3 Operating Principle&quot;">​</a></h2><p>Rotating the knob on the module adjusts the output analog value. Rotating clockwise increases the value, and rotating counterclockwise decreases the value.</p><h2 id="_3-4-hands-on-project" tabindex="-1">3.4 Hands-On Project <a class="header-anchor" href="#_3-4-hands-on-project" aria-label="Permalink to &quot;3.4 Hands-On Project&quot;">​</a></h2><h3 id="_3-4-1-project-overview" tabindex="-1">3.4.1 Project Overview <a class="header-anchor" href="#_3-4-1-project-overview" aria-label="Permalink to &quot;3.4.1 Project Overview&quot;">​</a></h3><p>This project uses the knob module to collect analog values corresponding to knob rotation and outputs them via the serial port. Rotating the knob allows observation of changing values in the serial monitor, demonstrating the analog acquisition principle of potentiometers.</p><h3 id="_3-4-2-hardware-wiring" tabindex="-1">3.4.2 Hardware Wiring <a class="header-anchor" href="#_3-4-2-hardware-wiring" aria-label="Permalink to &quot;3.4.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the knob module to port <strong>P5</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="620" src="'+s+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This module supports connection to any port among P5, P6, P7, or P8 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_3-4-3-adding-extensions" tabindex="-1">3.4.3 Adding Extensions <a class="header-anchor" href="#_3-4-3-adding-extensions" aria-label="Permalink to &quot;3.4.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Knob module</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_3-4-4-complete-program-and-analysis" tabindex="-1">3.4.4 Complete Program and Analysis <a class="header-anchor" href="#_3-4-4-complete-program-and-analysis" aria-label="Permalink to &quot;3.4.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, the analog value of the knob module on port P5 is continuously read.</p></li><li><p>The acquired knob value is output via the serial port.</p></li><li><p>A 0.1 s delay is executed to refresh data quickly and track knob position changes.</p></li></ol><img loading="lazy" height="326" width="939" src="'+c+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">01 Program Files/03 Knob Module.sb3</a>.</strong></p></div><h3 id="_3-4-5-program-upload" tabindex="-1">3.4.5 Program Upload <a class="header-anchor" href="#_3-4-5-program-upload" aria-label="Permalink to &quot;3.4.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h3 id="_3-4-6-program-outcome" tabindex="-1">3.4.6 Program Outcome <a class="header-anchor" href="#_3-4-6-program-outcome" aria-label="Permalink to &quot;3.4.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, observe the serial monitor in the lower-right corner of the programming software. Rotating the knob counterclockwise decreases the output value. Rotating clockwise increases the printed value, with values ranging from 0 to 255.</p><img loading="lazy" height="904" width="1308" src="'+d+'" class="common_img" style="width:500px;">',28)])])}const k=o(h,[["render",p]]);export{y as __pageData,k as default};
